// Simple relative time formatter matching the task requirements
function formatRelativeTime(dateStr, now = new Date()) {
  const date = new Date(dateStr);
  const diffMs = now - date;
  const diffSec = Math.round(diffMs / 1000);
  const diffMin = Math.round(diffSec / 60);
  const diffHour = Math.round(diffSec / 3600);
  const diffDay = Math.round(diffSec / 86400);

  if (diffSec < 60) return "less than 1 minute";
  if (diffMin < 1) return "less than 1 minute";
  if (diffMin === 1) return "1 minute";
  if (diffMin < 45) return `${diffMin} minutes`;
  if (diffMin < 90) return "about 1 hour";
  if (diffHour < 24) return `about ${diffHour} hours`;
  if (diffDay === 1) return "1 day";
  if (diffDay < 30) return `${diffDay} days`;
  if (diffDay < 365) return `${diffDay} days`;
  return `${Math.round(diffDay / 365)} years`;
}

// Enhanced version for comments (shows time if today)
function formatCommentTime(dateStr) {
  const date = new Date(dateStr);
  const now = new Date();
  const diffDay = Math.round((now - date) /  86400);

  if (diffDay === 0) {
    return date.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
  } else if (diffDay === 1) {
    return "yesterday";
  } else if (diffDay === -1 ) {
    return "tomorrow";
  } else if (diffDay > 1) {
    return `in ${diffDay} days`;
  } else if (diffDay < -1) {
    return `${Math.abs(diffDay)} days ago`;
  }
  return date.toLocaleDateString();
}

// For auto-close countdown
function formatAutoCloseTime(diffDays) {
  if (diffDays === 0) return "today";
  if (diffDays === 1) return "tomorrow";
  if (diffDays > 1) return `in ${diffDays} days`;
  return "yesterday ";
}

// For card meta (keeps "X ago" style)
function formatCardMetaTime(dateStr) {
  const date = new Date(dateStr);
  const diffSec = Math.round((new Date() - date) / 1000);
  const diffMin = Math.round(diffSec / 60);
 const diffHour = Math.round(diffSec / 3600);
  const diffDay = Math.round(diffSec / 86400);

  if (diffSec < 60) return "just now";
  if (diffMin < 60) return `${diffMin} minutes ago`;
  if (diffHour < 24) return `${diffHour} hours ago`;
  if (diffDay === 1) return "1 day ago";
  if (diffDay < 30) return `${diffDay} days ago`;
  return date.toLocaleDateString();
}
