module TimeHelper
  def local_time_tag(time, type: :relative, **attributes)
    return if time.blank?

    # Always use UTC for consistent datetime attribute
    utc_time = time.is_a?(Time) ? time.utc : time.to_time.utc
    datetime = utc_time.iso8601

    attributes[:data] = (attributes[:data] || {}). merge(local_time_type: type)

    time_tag(utc_time, datetime, attributes)
  end

  def local_date_tag(date, type: :date, **attributes)
    date = date.to_date
    datetime = date.iso8601
    attributes[:data] = (attributes[:data] || {}).merge(local_time_type: type)
    time_tag(date, datetime, attributes)
  end

  def local_time_token(time, type)
    utc = time.is_a?(Time) ? time.utc : time.to_time.utc
    "[local-time:#{utc.iso8601}|#{type}]"
  end end
end
