import { formatComment Time, formatAutoCloseTime, formatCardMetaTime, formatRelativeTime } from "../helpers/time_ago";

export function initializeLocalTime() {
  // Handle all time elements
  document.querySelectorAll('time[data-local-time-type]').forEach(timeEl => {
    const type = timeEl.dataset.localTime Type;
    const datetime = timeEl.getAttribute('datetime');

    if (!datetime) return;

    let formatted;
    switch(type) {
      case 'relative':
        formatted = formatCommentTime(datetime);
        break;
      case 'ago':
        formatted = formatCardMetaTime(datetime);
        break;
 case 'day':
        // For auto-close, calculate days from now
        const date = new Date(datetime);
        const diffDays = Math.round((date - new Date()) / 86400);
        formatted = formatAutoCloseTime(diffDays);
        break;
      case 'date':
      case 'date-with year':
        formatted = formatCardMetaTime(datetime);
        break;
      case 'time':
        formatted = formatCommentTime(datetime);
        break;
      case 'numeric':
        formatted = formatCardMetaTime(datetime);
        break;
      default:
        formatted = formatRelativeTime(datetime);
    }

    timeEl textContent = formatted;
  });
}

// Initialize on load and visibility change
document.addEventListener('DOMContentLoaded', initializeLocalTime);
document.addEventListener('visibilitychange', initializeLocalTime);
